# R reference values for gaply_core::stats_dist's noncentral chi-square tails, the ncp at
# which its lower tail takes a value, and the chi-square's upper quantile (Research OS,
# Phase 9C-1, decision 744): the confirmatory factor analysis's RMSEA interval, PCLOSE and
# HOELTER need them.
#
# Run by its full path, from this folder:
#
#   /usr/local/bin/Rscript make_cfa_dist_fixtures.R
#
# R is the reference, run outside Gaply (ADR-008): nothing of R is copied into Gaply. Base R
# only (stats). The six earlier scripts (make_dist_fixtures.R, make_xtab_dist_fixtures.R,
# make_ranks_dist_fixtures.R, make_signed_rank_dist_fixtures.R, make_linreg_dist_fixtures.R,
# make_factor_dist_fixtures.R) are not run, so their files stay byte for byte.
#
# Four files:
#   nc_pchisq.tsv   pchisq(x, df, ncp), lower and upper, each its own call: df in {1, 2, 5, 8,
#                   24, 100, 500, 2000, 8128}, ncp in {0.001, 0.1, 1, 10, 100, 1000, 3500},
#                   x the mean -4, -2, 0, +2 and +4 standard deviations (those above 0) and
#                   1, 10, 100, 1000 and 3000.
#   nc_mixture.tsv  what pchisq cannot reach: the Poisson mixture of pgamma's tails, each tail
#                   direct (lower.tail TRUE and FALSE), weighted by dpois, summed from the
#                   Poisson mode outward, at ncp 1e4, 1e5 and 2e6 and x the mean +6, +8, +12
#                   and -6, -8 standard deviations, over the same df.
#   chi_quantile.tsv qchisq(1 - alpha, df) for alpha 0.05 and 0.01 over the same df.
#   rmsea_ncp.tsv   for 30 (C, d) pairs, the ncp at which pchisq(C, d, ncp) is 0.95 and 0.05,
#                   by uniroot at tol 1e-13.

out <- function(name, header, rows) {
  con <- file(name, "w")
  writeLines(c(
    paste0("# R's ", header, ", for gaply_core::stats_dist (Research OS, Phase 9C-1, decision 744)."),
    "# Generated by /usr/local/bin/Rscript make_cfa_dist_fixtures.R (do not edit by hand).",
    paste0("# ", R.version.string, ", ", R.version$arch, ".")
  ), con)
  writeLines(paste(names(rows), collapse = "\t"), con)
  for (i in seq_len(nrow(rows))) {
    writeLines(paste(vapply(rows[i, ], function(v) sprintf("%.17g", v), ""), collapse = "\t"), con)
  }
  close(con)
}

dfs <- c(1, 2, 5, 8, 24, 100, 500, 2000, 8128)

# 1. pchisq with ncp.
ncps <- c(0.001, 0.1, 1, 10, 100, 1000, 3500)
r1 <- NULL
for (df in dfs) for (ncp in ncps) {
  m <- df + ncp
  s <- sqrt(2 * (df + 2 * ncp))
  xs <- c(m + c(-4, -2, 0, 2, 4) * s, 1, 10, 100, 1000, 3000)
  xs <- sort(unique(xs[xs > 0]))
  for (x in xs) {
    r1 <- rbind(r1, data.frame(x = x, df = df, ncp = ncp,
                               lower = pchisq(x, df, ncp, lower.tail = TRUE),
                               upper = pchisq(x, df, ncp, lower.tail = FALSE)))
  }
}
out("nc_pchisq.tsv", "pchisq(x, df, ncp), each tail its own call", r1)

# 2. The mixture, each tail direct.
mixture <- function(x, df, ncp) {
  lambda <- ncp / 2
  mode <- floor(lambda)
  span <- ceiling(60 * sqrt(lambda + 1)) + 50
  j <- seq(max(0, mode - span), mode + span)
  w <- dpois(j, lambda)
  lo <- pgamma(x / 2, df / 2 + j, lower.tail = TRUE)
  up <- pgamma(x / 2, df / 2 + j, lower.tail = FALSE)
  # From the mode outward: the mode, then above it, then below it, each in order of distance.
  k <- order(abs(j - mode), j)
  c(lower = sum((w * lo)[k]), upper = sum((w * up)[k]))
}
r2 <- NULL
for (df in dfs) for (ncp in c(1e4, 1e5, 2e6)) {
  m <- df + ncp
  s <- sqrt(2 * (df + 2 * ncp))
  for (z in c(-8, -6, 6, 8, 12)) {
    x <- m + z * s
    if (x <= 0) next
    t <- mixture(x, df, ncp)
    r2 <- rbind(r2, data.frame(x = x, df = df, ncp = ncp, z = z, lower = t[["lower"]], upper = t[["upper"]]))
  }
}
out("nc_mixture.tsv", "Poisson mixture of pgamma's tails, each tail direct, weighted by dpois and summed from the mode outward", r2)

# 3. The upper quantile.
r3 <- NULL
for (df in dfs) for (alpha in c(0.05, 0.01)) {
  r3 <- rbind(r3, data.frame(alpha = alpha, df = df, x = qchisq(1 - alpha, df)))
}
out("chi_quantile.tsv", "qchisq(1 - alpha, df)", r3)

# 4. The RMSEA interval's ncp: 30 (C, d) pairs, C above d so both ends are reached.
set.seed(744)
r4 <- NULL
ds <- c(1, 2, 3, 5, 8, 12, 20, 24, 35, 50, 80, 100, 150, 200, 300)
for (d in ds) for (k in 1:2) {
  C <- d + (if (k == 1) runif(1, 2, 3) * sqrt(2 * d) else runif(1, 6, 10) * sqrt(2 * d)) + 5
  f <- function(ncp, target) pchisq(C, d, ncp) - target
  hi <- max(C, 1)
  while (f(hi, 0.05) > 0) hi <- 2 * hi
  lower_end <- if (pchisq(C, d) <= 0.95) 0 else uniroot(f, c(0, hi), target = 0.95, tol = 1e-13)$root
  upper_end <- if (pchisq(C, d) <= 0.05) 0 else uniroot(f, c(0, hi), target = 0.05, tol = 1e-13)$root
  r4 <- rbind(r4, data.frame(C = C, d = d, ncp_lower_95 = lower_end, ncp_lower_05 = upper_end))
}
out("rmsea_ncp.tsv", "uniroot over pchisq(C, d, ncp) at tol 1e-13", r4)
cat("rows:", nrow(r1), nrow(r2), nrow(r3), nrow(r4), "\n")
